       Schema::connection($conn)->create('t_mahasiswa', function (Blueprint $table) {
           $table->id('id_mahasiswa');
           $table->unsignedBigInteger('id_user')->nullable();
           $table->unsignedBigInteger('id_prodi')->nullable();
           $table->string('npm')->nullable();
